/**
 * Embedded base64 strings of the official company logos
 * located in assets/company logos/
 */

export const GOLDILOCKS_LOGO_BASE64 = '';
export const CHAWNAH_FOODS_LOGO_BASE64 = '';
export const CAKE_OCCASIONS_LOGO_BASE64 = '';
export const FRESH_BERRY_LOGO_BASE64 = '';
export const CHI_LOGO_BASE64 = '';

export type CompanyLogoMatch = {
  logoBase64: string;
  name: string;
  isAffiliate: boolean;
};

export function resolveOperatingCompanyLogo(companyOrStoreName?: string | null): CompanyLogoMatch | null {
  if (!companyOrStoreName) return null;
  const norm = companyOrStoreName.toLowerCase();
  if (norm.includes('chawnah')) {
    return { logoBase64: CHAWNAH_FOODS_LOGO_BASE64, name: 'Chawnah Foods Inc.', isAffiliate: true };
  }
  if (norm.includes('fresh berry') || norm.includes('freshberry')) {
    return { logoBase64: FRESH_BERRY_LOGO_BASE64, name: 'Fresh Berry Foods Corp.', isAffiliate: true };
  }
  if (norm.includes('cake & occasion') || norm.includes('cakes and occasions') || norm.includes('cake haven')) {
    return { logoBase64: CAKE_OCCASIONS_LOGO_BASE64, name: 'Cakes and Occasions Corp.', isAffiliate: true };
  }
  if (norm.includes('chi') || norm.includes('central hub') || norm.includes('head office') || norm.includes('corporate')) {
    return { logoBase64: CHI_LOGO_BASE64, name: 'Cake Haven Inc. (CHI)', isAffiliate: true };
  }
  return null;
}
